import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const db = new DatabaseSync(process.env.DB_PATH || path.join(here, 'workboard.sqlite'));
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const send = (status, body, type = 'application/json; charset=utf-8') => {
    res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
    res.end(body);
  };
  try {
    if (req.method === 'GET' && url.pathname === '/health') return send(200, JSON.stringify({ status: 'ok' }));
    if (req.method === 'GET' && url.pathname === '/api/projects') {
      return send(200, JSON.stringify(db.prepare('SELECT id, name FROM projects ORDER BY id').all()));
    }
    if (req.method === 'POST' && url.pathname === '/api/projects') {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      let data;
      try { data = JSON.parse(raw); } catch { return send(400, JSON.stringify({ error: 'Invalid JSON' })); }
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return send(400, JSON.stringify({ error: 'Project name is required' }));
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return send(201, JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    }
    if (req.method === 'GET' && url.pathname.startsWith('/projects/')) {
      const id = url.pathname.slice('/projects/'.length);
      if (!/^\d+$/.test(id)) return send(404, 'Not found', 'text/plain; charset=utf-8');
      const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(id));
      if (!project) return send(404, 'Not found', 'text/plain; charset=utf-8');
      const html = await readFile(path.join(here, 'public', 'index.html'), 'utf8');
      return send(200, html, 'text/html; charset=utf-8');
    }
    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
      const html = await readFile(path.join(here, 'public', 'index.html'), 'utf8');
      return send(200, html, 'text/html; charset=utf-8');
    }
    if (req.method === 'GET' && url.pathname === '/app.js') {
      return send(200, await readFile(path.join(here, 'public', 'app.js'), 'utf8'), 'text/javascript; charset=utf-8');
    }
    if (req.method === 'GET' && url.pathname === '/style.css') {
      return send(200, await readFile(path.join(here, 'public', 'style.css'), 'utf8'), 'text/css; charset=utf-8');
    }
    send(404, 'Not found', 'text/plain; charset=utf-8');
  } catch (error) {
    console.error(error);
    if (!res.headersSent) send(500, JSON.stringify({ error: 'Internal server error' }));
  }
});
const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));

const view = document.querySelector('#project-view');
const pathMatch = location.pathname.match(/^\/projects\/(\d+)\/?$/);

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

async function showProjects() {
  view.replaceChildren();
  const form = element('form', undefined, 'create-form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.autocomplete = 'off';
  const button = element('button', 'Create project');
  button.type = 'submit';
  const alert = element('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  form.append(label, input, button, alert);
  const list = element('div', undefined, 'project-list');
  list.setAttribute('aria-label', 'Projects');
  view.append(form, list);

  async function refresh() {
    const response = await fetch('/api/projects');
    const projects = await response.json();
    list.replaceChildren();
    for (const project of projects) {
      const row = element('article', undefined, 'project-row');
      row.dataset.testid = 'project-row';
      row.append(element('span', project.name, 'project-name'));
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      row.append(open);
      list.append(row);
    }
  }
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (!response.ok) {
      const result = await response.json();
      alert.textContent = result.error;
      alert.hidden = false;
      return;
    }
    input.value = '';
    alert.hidden = true;
    await refresh();
  });
  await refresh();
}

async function showProject(id) {
  const response = await fetch('/api/projects');
  const projects = await response.json();
  const project = projects.find(item => String(item.id) === id);
  if (!project) {
    view.append(element('h2', 'Project not found'));
    const back = element('button', 'Projects');
    back.addEventListener('click', () => { location.href = '/'; });
    view.append(back);
    return;
  }
  const back = element('button', 'Projects', 'back-button');
  back.addEventListener('click', () => { location.href = '/'; });
  view.append(back, element('h2', project.name));
}

if (pathMatch) showProject(pathMatch[1]);
else showProjects();

* { box-sizing: border-box; }
body { margin: 0; background: #f4f6fa; color: #20283a; font-family: system-ui, sans-serif; }
.shell { max-width: 760px; margin: 48px auto; padding: 0 24px; }
.topbar { border-bottom: 1px solid #dce1e9; margin-bottom: 28px; }
h1 { font-size: 2rem; margin: 0 0 18px; }
h2 { font-size: 1.6rem; margin: 26px 0; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 10px 12px; align-items: end; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; padding: 11px 12px; border: 1px solid #aeb8c8; border-radius: 6px; font: inherit; }
button { border: 0; border-radius: 6px; background: #315fd1; color: white; padding: 11px 16px; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #244aaa; }
.create-form [role="alert"] { grid-column: 1 / -1; margin: 0; color: #b42318; }
.project-list { margin-top: 24px; display: grid; gap: 10px; }
.project-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px 16px; background: white; border: 1px solid #dce1e9; border-radius: 8px; }
.project-name { overflow-wrap: anywhere; font-weight: 600; }
.back-button { background: #e5eaf3; color: #20283a; }
.back-button:hover { background: #d7dfeb; }
@media (max-width: 480px) { .shell { margin-top: 24px; } .create-form { grid-template-columns: 1fr; } .create-form label { grid-column: auto; } }

